export function decodeCursor(cursor) {
  const text = Buffer.from(cursor, 'base64url').toString();
  if (!text.startsWith('id:')) return null;
  const id = Number.parseInt(text.slice(3), 10);
  if (Number.isNaN(id) || id < 1) return null;
  return id;
}

