bootforge/fullstack-crud/api-patterns/pa.solution:
function decode(cursor) {
  if (cursor === null) return 0;
  const text = Buffer.from(cursor, 'base64url').toString();
  if (!text.startsWith('id:')) return 0;
  const id = Number.parseInt(text.slice(3), 10);
  return Number.isNaN(id) || id < 1 ? 0 : id;
}

export function cursorPage(rows, cursor, limit) {
  const after = decode(cursor);
  const matching = rows.filter((r) => r.id > after);
  const data = matching.slice(0, limit);
  const nextCursor =
    matching.length > limit
      ? Buffer.from('id:' + data[data.length - 1].id).toString('base64url')
      : null;
  return { data, nextCursor };
}

