}

bootforge/fullstack-crud/api-patterns/pa.solution:
export function buildPageLinks(basePath, page, totalPages) {
  const link = (p) => basePath + '?page=' + p;
  return {
    self: link(page),
    prev: page > 1 ? link(page - 1) : null,
    next: page < totalPages ? link(page + 1) : null,
  };
}

