export function queryRows(rows, { filters, sort, page, limit }, allowedFields) {
  const requested = [...filters.map((f) => f.field), ...sort.map((s) => s.field)];
  const errors = requested
    .filter((f) => !allowedFields.includes(f))
    .map((f) => 'unknown field: ' + f);
  if (errors.length > 0) return { ok: false, errors };

  const matches = (row, { field, op, value }) => {
    if (op === 'eq') return row[field] === value;
    if (op === 'contains')
      return String(row[field]).toLowerCase().includes(String(value).toLowerCase());
    if (op === 'gte') return row[field] >= value;
    if (op === 'lte') return row[field] <= value;
    return false;
  };
  const filtered = rows.filter((row) => filters.every((f) => matches(row, f)));

  const sorted = [...filtered].sort((a, b) => {
    for (const { field, dir } of sort) {
      if (a[field] === b[field]) continue;
      const base = a[field] < b[field] ? -1 : 1;
      return dir === 'desc' ? -base : base;
    }
    return 0;
  });

  const total = sorted.length;
  const start = (page - 1) * limit;
  return {
    ok: true,
    data: sorted.slice(start, start + limit),
    meta: { page, totalPages: Math.ceil(total / limit), total },
  };
}

