export function requireAuth(req, nowMs) {
  const header = req.headers.authorization;
  if (typeof header !== 'string' || !header.startsWith('Bearer ') || header.length <= 7) {
    return { ok: false, status: 401, error: 'missing token' };
  }
  const token = header.slice(7);
  let payload;
  try {
    payload = JSON.parse(Buffer.from(token, 'base64url').toString());
  } catch {
    payload = null;
  }
  if (
    payload === null ||
    typeof payload !== 'object' ||
    typeof payload.sub !== 'string' ||
    typeof payload.exp !== 'number'
  ) {
    return { ok: false, status: 401, error: 'invalid token' };
  }
  if (payload.exp <= nowMs) {
    return { ok: false, status: 401, error: 'token expired' };
  }
  return { ok: true, userId: payload.sub };
}

