export function parseCacheControl(raw) {
  const result = { maxAge: null, noStore: false, noCache: false };
  for (const part of raw.split(',')) {
    const directive = part.trim();
    if (directive === 'no-store') result.noStore = true;
    else if (directive === 'no-cache') result.noCache = true;
    else if (directive.startsWith('max-age=')) {
      result.maxAge = Number.parseInt(directive.slice(8), 10);
    }
  }
  return result;
}

