export function makeCache({ ttlMs, now }) {
  const store = new Map();
  return {
    set(key, value) {
      store.set(key, { value, storedAt: now() });
    },
    get(key) {
      const entry = store.get(key);
      if (!entry) return null;
      if (now() - entry.storedAt >= ttlMs) {
        store.delete(key);
        return null;
      }
      return entry.value;
    },
    size() {
      return store.size;
    },
  };
}

