import { createHash } from 'node:crypto';

export function makeCachedHandler({ loader, ttlMs, now }) {
  const cache = new Map();
  return (req, res) => {
    const entry = cache.get(req.path);
    let body;
    if (entry && now() - entry.storedAt < ttlMs) {
      body = entry.body;
    } else {
      body = loader(req.path);
      cache.set(req.path, { body, storedAt: now() });
    }
    const etag =
      '"' + createHash('sha256').update(JSON.stringify(body)).digest('hex') + '"';
    res.set('etag', etag);
    if (req.headers['if-none-match'] === etag) {
      res.status(304).json(null);
      return;
    }
    res.status(200).json(body);
  };
}

