export function makeRepo(seedRows) {
  const rows = seedRows.map((r) => ({ ...r }));
  const nextId = () => (rows.length === 0 ? 1 : Math.max(...rows.map((r) => r.id)) + 1);
  return {
    findAll() {
      return rows.map((r) => ({ ...r }));
    },
    findById(id) {
      const row = rows.find((r) => r.id === id);
      return row ? { ...row } : null;
    },
    insert(data) {
      const row = { ...data, id: nextId() };
      rows.push(row);
      return { ...row };
    },
    update(id, patch) {
      const index = rows.findIndex((r) => r.id === id);
      if (index === -1) return null;
      rows[index] = { ...rows[index], ...patch, id };
      return { ...rows[index] };
    },
    remove(id) {
      const index = rows.findIndex((r) => r.id === id);
      if (index === -1) return false;
      rows.splice(index, 1);
      return true;
    },
  };
}

