export function makeSoftRepo(seedRows, now) {
  const rows = seedRows.map((r) => ({ deletedAt: null, ...r }));
  const locate = (id) => rows.find((r) => r.id === id);
  return {
    findAll() {
      return rows.filter((r) => r.deletedAt === null).map((r) => ({ ...r }));
    },
    findById(id) {
      const row = locate(id);
      return row ? { ...row } : null;
    },
    remove(id) {
      const row = locate(id);
      if (!row || row.deletedAt !== null) return false;
      row.deletedAt = now();
      return true;
    },
    restore(id) {
      const row = locate(id);
      if (!row || row.deletedAt === null) return false;
      row.deletedAt = null;
      return true;
    },
  };
}

