export function makeAuditedRepo({ seedRows, now }) {
  const rows = seedRows.map((r) => ({ ...r }));
  const log = [];
  const record = (action, id) => log.push({ action, id, at: now() });
  return {
    findAll() {
      return rows.map((r) => ({ ...r }));
    },
    findById(id) {
      const row = rows.find((r) => r.id === id);
      return row ? { ...row } : null;
    },
    insert(data) {
      const id = rows.length === 0 ? 1 : Math.max(...rows.map((r) => r.id)) + 1;
      const row = { ...data, id };
      rows.push(row);
      record('insert', id);
      return { ...row };
    },
    update(id, patch) {
      const index = rows.findIndex((r) => r.id === id);
      if (index === -1) return null;
      rows[index] = { ...rows[index], ...patch, id };
      record('update', id);
      return { ...rows[index] };
    },
    remove(id) {
      const index = rows.findIndex((r) => r.id === id);
      if (index === -1) return false;
      rows.splice(index, 1);
      record('remove', id);
      return true;
    },
    history() {
      return log.map((e) => ({ ...e }));
    },
  };
}

