export function planTransfer(balances, from, to, cents) {
  const available = balances[from];
  if (available === undefined || available < cents) {
    return { ok: false, error: 'insufficient funds' };
  }
  return {
    ok: true,
    balances: {
      ...balances,
      [from]: available - cents,
      [to]: (balances[to] ?? 0) + cents,
    },
  };
}

