export function applyLedger(balances, entries) {
  const next = { ...balances };
  const failedIndices = [];
  entries.forEach(({ from, to, cents }, index) => {
    if (next[from] === undefined || next[from] < cents) {
      failedIndices.push(index);
      return;
    }
    next[from] -= cents;
    next[to] = (next[to] ?? 0) + cents;
  });
  return { balances: next, failedIndices };
}

