export function placeOrder(db, customer, items) {
  db.exec('BEGIN');
  try {
    const deduct = db.prepare('UPDATE products SET stock = stock - ? WHERE id = ? AND stock >= ?');
    const priceOf = db.prepare('SELECT price_cents FROM products WHERE id = ?');
    let totalCents = 0;
    for (const { productId, qty } of items) {
      const info = deduct.run(qty, productId, qty);
      if (info.changes !== 1) {
        db.exec('ROLLBACK');
        return { ok: false, error: 'out of stock: ' + productId };
      }
      totalCents += priceOf.get(productId).price_cents * qty;
    }
    const orderInfo = db
      .prepare('INSERT INTO orders (customer, total_cents) VALUES (?, ?)')
      .run(customer, totalCents);
    const orderId = Number(orderInfo.lastInsertRowid);
    const insertItem = db.prepare(
      'INSERT INTO order_items (order_id, product_id, qty) VALUES (?, ?, ?)'
    );
    for (const { productId, qty } of items) {
      insertItem.run(orderId, productId, qty);
    }
    db.exec('COMMIT');
    return { ok: true, orderId, totalCents };
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

