export function validateMigrationIds(migrations) {
  const errors = [];
  const seen = new Set();
  let prev = null;
  for (const { id } of migrations) {
    if (seen.has(id)) {
      errors.push('duplicate id: ' + id);
      continue;
    }
    seen.add(id);
    if (prev !== null && id <= prev) {
      errors.push('out of order: ' + id);
    }
    prev = id;
  }
  if (errors.length === 0) return { ok: true };
  return { ok: false, errors };
}

