export function makeMigrator(db, migrations) {
  const appliedSet = () =>
    new Set(db.prepare('SELECT id FROM _migrations').all().map((r) => r.id));
  const record = () => db.prepare('INSERT INTO _migrations (id) VALUES (?)');

  function applyUntil(stopId) {
    if (stopId !== null && !migrations.some((m) => m.id === stopId)) return [];
    const applied = appliedSet();
    const insert = record();
    const done = [];
    for (const m of migrations) {
      if (!applied.has(m.id)) {
        db.exec(m.sql);
        insert.run(m.id);
        done.push(m.id);
      }
      if (stopId !== null && m.id === stopId) break;
    }
    return done;
  }

  return {
    status() {
      const applied = appliedSet();
      return {
        applied: migrations.filter((m) => applied.has(m.id)).map((m) => m.id),
        pending: migrations.filter((m) => !applied.has(m.id)).map((m) => m.id),
      };
    },
    up() {
      return applyUntil(null);
    },
    upTo(id) {
      return applyUntil(id);
    },
  };
}

