function sanitize(body, spec) {
  const clean = {};
  for (const [field, rules] of Object.entries(spec)) {
    let value = body[field];
    if (value === undefined) continue;
    if (typeof value === 'string') value = value.trim();
    if (rules.type === 'number' && typeof value === 'string' && value !== '') {
      const n = Number(value);
      if (!Number.isNaN(n)) value = n;
    }
    clean[field] = value;
  }
  return clean;
}

function validate(body, spec) {
  const errors = {};
  for (const [field, rules] of Object.entries(spec)) {
    const value = body[field];
    if (value === undefined) {
      if (rules.required) errors[field] = ['required'];
      continue;
    }
    if (rules.type && typeof value !== rules.type) {
      errors[field] = ['expected ' + rules.type];
      continue;
    }
    const fieldErrors = [];
    if (rules.min !== undefined && value < rules.min) fieldErrors.push('must be >= ' + rules.min);
    if (rules.max !== undefined && value > rules.max) fieldErrors.push('must be <= ' + rules.max);
    if (rules.enum && !rules.enum.includes(value))
      fieldErrors.push('must be one of: ' + rules.enum.join(', '));
    if (rules.pattern && !new RegExp(rules.pattern).test(value))
      fieldErrors.push('invalid format');
    if (fieldErrors.length > 0) errors[field] = fieldErrors;
  }
  if (Object.keys(errors).length === 0) return { ok: true };
  return { ok: false, errors };
}

export function withValidation(spec, handler) {
  return (req, res) => {
    const clean = sanitize(req.body, spec);
    const result = validate(clean, spec);
    if (!result.ok) {
