export function processResponses(state, responses) {
  let current = state;
  for (const response of responses) {
    const target = current.pending.find((op) => op.opId === response.opId);
    if (!target) continue;
    if (response.ok) {
      current = {
        serverItems: response.serverItems ?? current.serverItems,
        pending: current.pending.filter((op) => op.opId !== response.opId),
      };
    } else {
      const retries = (target.retries ?? 0) + 1;
      current = {
        ...current,
        pending:
          retries >= 3
            ? current.pending.filter((op) => op.opId !== response.opId)
            : current.pending.map((op) =>
                op.opId === response.opId ? { ...op, failed: true, retries } : op
              ),
      };
    }
  }
  return current;
}

