function authenticate(req, nowMs) {
  const header = req.headers.authorization;
  if (typeof header !== 'string' || !header.startsWith('Bearer ') || header.length <= 7) {
    return { ok: false, error: 'missing token' };
  }
  let payload;
  try {
    payload = JSON.parse(Buffer.from(header.slice(7), 'base64url').toString());
  } catch {
    payload = null;
  }
  if (
    payload === null ||
    typeof payload !== 'object' ||
    typeof payload.sub !== 'string' ||
    typeof payload.exp !== 'number'
  ) {
    return { ok: false, error: 'invalid token' };
  }
  if (payload.exp <= nowMs) return { ok: false, error: 'token expired' };
  return { ok: true, userId: payload.sub };
}

