export function makeApi(db) {
  const notFound = (res) => res.status(404).json({ error: 'not found' });
  const getById = (id) => {
    const row = db.prepare('SELECT id, title, done FROM todos WHERE id = ?').get(id);
    return row ? { ...row } : null;
  };

  return {
    handle(req, res) {
      const { method, path } = req;
      const idMatch = path.match(/^\/todos\/([^/]+)$/);

      if (method === 'POST' && path === '/todos') {
        const title = req.body?.title;
        if (typeof title !== 'string' || title.trim() === '') {
          res.status(400).json({ error: 'title is required' });
          return;
        }
        const info = db.prepare('INSERT INTO todos (title) VALUES (?)').run(title.trim());
        const id = Number(info.lastInsertRowid);
        res.status(201).json(getById(id));
        return;
      }

      if (method === 'GET' && path === '/todos') {
        const rows = db
          .prepare('SELECT id, title, done FROM todos ORDER BY id')
          .all()
          .map((r) => ({ ...r }));
        res.status(200).json(rows);
        return;
      }

      if (idMatch) {
        const id = Number(idMatch[1]);
        if (method === 'GET') {
          const row = getById(id);
          if (!row) return void notFound(res);
          res.status(200).json(row);
          return;
        }
        if (method === 'PATCH') {
          const row = getById(id);
          if (!row) return void notFound(res);
          const title = typeof req.body?.title === 'string' ? req.body.title : row.title;
          const done = typeof req.body?.done === 'number' ? req.body.done : row.done;
          db.prepare('UPDATE todos SET title = ?, done = ? WHERE id = ?').run(title, done, id);
          res.status(200).json(getById(id));
          return;
        }
        if (method === 'DELETE') {
          const info = db.prepare('DELETE FROM todos WHERE id = ?').run(id);
          if (info.changes !== 1) return void notFound(res);
          res.status(204).json(null);
          return;
        }
      }

      notFound(res);
    },
  };
}

