      let filtered = rows;
      if (query.done !== undefined) {
        if (query.done !== 'true' && query.done !== 'false') {
          res.status(400).json({ error: 'done must be true or false' });
          return;
        }
        const want = query.done === 'true';
        filtered = rows.filter((t) => t.done === want);
      }

      let page = Number.parseInt(query.page, 10);
      if (Number.isNaN(page) || page < 1) page = 1;
      let limit = Number.parseInt(query.limit, 10);
      if (Number.isNaN(limit)) limit = 10;
      limit = Math.min(50, Math.max(1, limit));

      const total = filtered.length;
      const start = (page - 1) * limit;
      res.status(200).json({
        data: filtered.slice(start, start + limit).map((t) => ({ ...t })),
        meta: { page, totalPages: Math.ceil(total / limit), total },
      });
    },
  };
}
